/* Advanced SIMD in the gadget engine's AArch32 builder. The gadgets are
 * generated by engine/a32_neon.py, which documents the groups, the variant
 * index and the operand words this file packs. */
#include "translator.hpp"

#include <algorithm>
#include <bit>

namespace uml::cpu::arm64::gadgets::a32::detail {

Translator::Result Translator::emit_neon(const Instruction &in,
					 const FormPlan &plan)
{
	const auto &o = in.operands;
	/* VTRN of a register with itself: the oracle swaps the words of each D
	 * register, which is VREV64 of the 32-bit lanes (the result is UNKNOWN,
	 * and the corpus records the oracle's). */
	const std::uint8_t id = (plan.sub == neon_group::vtrn && o.d == o.m &&
				 o.esize == 32) ? neon_group::vrev64 : plan.sub;
	const NeonGroup &group = kNeonGroups[id];
	/* The Q forms are named _Q only when the encoding's Q bit is the whole
	 * distinction; the operands say which it is. */
	const unsigned q = (o.regs == 2 || o.quadword_operation) ? 1U : 0U;
	unsigned sign = 0;
	unsigned alt = 0;
	switch (group.selector) {
	case NeonSelector::none:
		break;
	case NeonSelector::usign:
		sign = o.unsigned_ ? 1U : 0U;
		break;
	case NeonSelector::src_unsigned:
		sign = o.src_unsigned ? 1U : 0U;
		break;
	case NeonSelector::floating:
		alt = o.floating_point ? 1U : 0U;
		break;
	case NeonSelector::polynomial:
		alt = o.polynomial ? 1U : 0U;
		break;
	case NeonSelector::unsigned_poly:
		sign = o.unsigned_ ? 1U : 0U;
		alt = o.polynomial ? 1U : 0U;
		break;
	case NeonSelector::scalar:
		alt = o.scalar_form ? 1U : 0U;
		break;
	case NeonSelector::vcge:
		sign = o.vtype_vcge == VCGEType::unsigned_ ? 1U : 0U;
		alt = o.vtype_vcge == VCGEType::fp ? 1U : 0U;
		break;
	case NeonSelector::vcgt:
		sign = o.vtype_vcgt == VCGTtype::unsigned_ ? 1U : 0U;
		alt = o.vtype_vcgt == VCGTtype::fp ? 1U : 0U;
		break;
	case NeonSelector::ceq:
		alt = o.int_operation ? 0U : 1U;
		break;
	case NeonSelector::cvt_int:
		sign = o.unsigned_ ? 1U : 0U;
		alt = o.to_integer ? 1U : 0U;
		break;
	case NeonSelector::cvt_fixed:
		sign = o.unsigned_ ? 1U : 0U;
		alt = o.to_fixed ? 1U : 0U;
		break;
	}
	unsigned size = 0;
	if (!group.size_none && o.esize >= 8)
		size = static_cast<unsigned>(
			std::countr_zero(static_cast<unsigned>(o.esize) / 8U));

	unsigned index = 0;
	switch (group.index) {
	case NeonIndex::generic:
		index = size | q << 2 | sign << 3 | alt << 4;
		break;
	case NeonIndex::ext:
		index = static_cast<unsigned>(o.position) / 8U | q << 4;
		break;
	case NeonIndex::tbl:
		index = static_cast<unsigned>(o.length) - 1U;
		break;
	case NeonIndex::fixed:
		index = static_cast<unsigned>(o.frac_bits) - 1U | q << 5 |
			sign << 6 | alt << 7 | (o.esize == 16 ? 1U << 8 : 0U);
		break;
	case NeonIndex::single:
		index = 0;
		break;
	case NeonIndex::lane: {
		const unsigned lane = group.indexed ?
			static_cast<unsigned>(o.index_value) & 7U : 0U;
		const unsigned rotation = group.rot_mask != 0 ?
			in.word >> group.rot_shift & group.rot_mask : 0U;
		index = lane | q << 3 | rotation << 4 |
			(o.esize == 16 ? 1U << 6 : 0U);
		break;
	}
	case NeonIndex::qshlu: {
		static constexpr unsigned base[4] = {0, 8, 24, 56};
		index = q * 120U + base[size & 3U] +
			static_cast<unsigned>(o.shift_amount);
		break;
	}
	}
	G which = G::count;
	if (index < group.count)
		which = kNeon[group.base + index];
	if (which == G::count) {
		/* A variant the group has no gadget for: the illegal-instruction
		 * exit, which the forms test turns into a failure. */
		emit_illegal();
		return {true, false};
	}

	const bool by_scalar = group.scalar == NeonScalar::always ||
			       (group.scalar == NeonScalar::alt && alt != 0);
	const auto element = [&o]() noexcept {
		return d_register(o.m) + static_cast<std::uint64_t>(o.index_value) *
					       (static_cast<unsigned>(o.esize) / 8U);
	};
	push(which);
	switch (group.shape) {
	case NeonShape::dnm:
		push(d_register(o.d) | d_register(o.n) << 16 |
		     (by_scalar ? element() : d_register(o.m)) << 32);
		break;
	case NeonShape::dnm_s: {
		/* The sources are S registers in a D-register variant. */
		const auto source = [q](int number) noexcept {
			return q != 0 ? d_register(number) : s_register(number);
		};
		push(d_register(o.d) | source(o.n) << 16 | source(o.m) << 32);
		break;
	}
	case NeonShape::dm:
		push(d_register(o.d) | d_register(o.m) << 16);
		break;
	case NeonShape::dmsh:
		push(d_register(o.d) | d_register(o.m) << 16);
		push(static_cast<std::uint8_t>(group.shift * o.shift_amount));
		break;
	case NeonShape::imm:
		push(d_register(o.d));
		push(o.imm64 != 0 ? o.imm64 : o.imm);
		break;
	case NeonShape::dcore:
		push(d_register(o.d) | core(o.t) << 16);
		break;
	case NeonShape::delem:
		push(d_register(o.d) | element() << 16);
		break;
	}
	return {};
}

/* VLDn and VSTn (engine/a32_structure.py): [gadget][key][word0][slots]
 * [library operand]. A combination the generator has no gadget for, and a
 * register list that runs past D31, are left to the library. */
Translator::Result Translator::emit_structure(const Instruction &in,
					      const FormPlan &plan)
{
	const auto &o = in.operands;
	const unsigned store = plan.sub & 1U;
	const unsigned shape = plan.sub >> 1 & 3U;
	const unsigned structs = (plan.sub >> 3 & 3U) + 1U;
	const unsigned ebytes = static_cast<unsigned>(o.ebytes);
	const unsigned log2 = ebytes == 2 ? 1U : ebytes == 4 ? 2U : 0U;
	const int dregs[4] = {o.d, o.d2, o.d3, o.d4};
	std::uint64_t slots[4] = {0, 0, 0, 0};
	unsigned variant = 0;
	bool in_range = true;
	const auto slot_of = [&in_range](int reg, unsigned k, std::uint64_t byte,
					 std::uint64_t (&out)[4]) {
		if (reg < 0 || reg > 31)
			in_range = false;
		else
			out[k] = d_register(reg) + byte;
	};
	switch (shape) {
	case 0: /* multiple structures */
		if (structs == 1) {
			variant = static_cast<unsigned>(o.regs) - 1U;
			if (o.d + o.regs > 32)
				in_range = false;
			slot_of(o.d, 0, 0, slots);
		} else if (structs == 2) {
			variant = static_cast<unsigned>(o.pairs) - 1U;
			for (int pair = 0; pair < o.pairs; ++pair) {
				slot_of(o.d + pair, 2U * static_cast<unsigned>(pair), 0, slots);
				slot_of(o.d2 + pair, 2U * static_cast<unsigned>(pair) + 1U, 0, slots);
			}
		} else {
			for (unsigned s = 0; s < structs; ++s)
				slot_of(dregs[s], s, 0, slots);
		}
		break;
	case 1: /* one lane */
		for (unsigned s = 0; s < structs; ++s)
			slot_of(dregs[s], s,
				static_cast<std::uint64_t>(o.index_value) * ebytes, slots);
		break;
	default: /* all lanes */
		if (structs == 1) {
			variant = static_cast<unsigned>(o.regs) - 1U;
			slot_of(o.d, 0, 0, slots);
			slot_of(o.d + (o.regs - 1), 1, 0, slots);
		} else {
			for (unsigned s = 0; s < structs; ++s)
				slot_of(dregs[s], s, 0, slots);
		}
		break;
	}
	G which = G::count;
	if (in_range && variant < 4 && !(o.wback && o.n == 15))
		which = kNeonMem[store][shape][structs - 1][log2][variant];
	if (which == G::count)
		return emit_library(in);
	/* A copy, hinted or not, and a VLD1 to all lanes have gadgets of their
	 * own; the hinted copy and the VLD1 to all lanes take the alignment
	 * mask in word1's bits 32-39, above the one or two slots they use. */
	const unsigned writeback = !o.wback ? 0U : o.register_index ? 2U : 1U;
	bool mask_in_word1 = false;
	if (shape == 0 && structs == 1) {
		const bool hinted = o.alignment > 1;
		const G fast = hinted ? kNeonCopyHint[store][variant][writeback] :
					kNeonCopy[store][variant][writeback];
		if (fast != G::count) {
			which = fast;
			mask_in_word1 = hinted;
		}
	} else if (shape == 2 && structs == 1 && !store && variant < 2) {
		const G fast = kNeonAllFast[log2][variant][writeback];
		if (fast != G::count) {
			which = fast;
			mask_in_word1 = true;
		}
	}
	/* A copy without writeback whose base the ADD or SUB still absorbable
	 * computed: the fused gadget does the ADD, then the copy, and the ADD's
	 * words leave the stream. Only Advanced SIMD data processing that reads
	 * no core register came between (run()), so doing the ADD here is
	 * invisible: no exit or fault in between can see Rd. */
	if (shape == 0 && structs == 1 && o.alignment <= 1 && !o.wback &&
	    in.cond == 14 && !in.in_it && in_range && which != G::count &&
	    address_add_.start != ~std::size_t{} && o.n != 15 &&
	    address_add_.rd == static_cast<std::uintptr_t>(o.n) * 8U &&
	    kNeonCopyAdd[store][variant] != G::count) {
		const auto add = address_add_;
		address_add_.start = ~std::size_t{};
		auto *data = words_.data();
		std::copy(data + add.end, data + words_.size(), data + add.start);
		words_.truncate(words_.size() - (add.end - add.start));
		std::uint64_t word1 = 0;
		for (unsigned k = 0; k < 4; ++k)
			word1 |= slots[k] << (16U * k);
		push(kNeonCopyAdd[store][variant]);
		push(key_);
		push(add.rn | std::uint64_t{add.rd} << 16 |
		     std::uint64_t{add.immediate} << 32);
		push(word1);
		push(library_operand(in));
		return {};
	}
	const std::uintptr_t rn = source(o.n, scratch0);
	std::uintptr_t rm = 0;
	if (o.wback && o.register_index)
		rm = source(o.m, scratch1);
	std::uint64_t word0 = std::uint64_t{rn} | (o.wback ? std::uint64_t{1} << 15 : 0U);
	if (o.wback && o.register_index)
		word0 |= std::uint64_t{rm} << 16 | std::uint64_t{1} << 31;
	if (o.alignment > 1)
		word0 |= static_cast<std::uint64_t>(o.alignment - 1) << 32;
	std::uint64_t word1 = 0;
	for (unsigned k = 0; k < 4; ++k)
		word1 |= slots[k] << (16U * k);
	if (mask_in_word1 && o.alignment > 1)
		word1 |= static_cast<std::uint64_t>(o.alignment - 1) << 32;
	push(which);
	push(key_);
	push(word0);
	push(word1);
	push(library_operand(in));
	return {};
}

} // namespace uml::cpu::arm64::gadgets::a32::detail
